import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { createMeeting, getUsers } from '../../api';

function PrincipalSchedule() {
  const navigate = useNavigate();
  const [users, setUsers] = useState([]);
  const [form, setForm] = useState({ title: '', agenda: '', date: '', time: '', meetingLink: '', venue: '', selectedStaff: [], selectedHods: [] });
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    getUsers().then(r => setUsers(r.data)).catch(console.error);
  }, []);

  const hods = users.filter(u => u.role === 'hod' && u.isApproved && !u.isBlacklisted);
  const staff = users.filter(u => u.role === 'staff' && !u.isBlacklisted);

  const toggleSelect = (id, field) => {
    const list = form[field];
    setForm({ ...form, [field]: list.includes(id) ? list.filter(x => x !== id) : [...list, id] });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');
    if (!form.title || !form.date || !form.time) return setError('Title, date and time are required');
    setLoading(true);
    try {
      const attendees = [...form.selectedStaff, ...form.selectedHods];
      await createMeeting({ title: form.title, agenda: form.agenda, date: form.date, time: form.time, meetingLink: form.meetingLink, venue: form.venue, attendees });
      alert('Meeting scheduled successfully!');
      navigate('/principal/dashboard');
    } catch (err) {
      setError(err.response?.data?.message || 'Failed to schedule');
    } finally { setLoading(false); }
  };

  const listStyle = { border: '1px solid #d1d5db', borderRadius: '8px', maxHeight: '160px', overflowY: 'auto', padding: '0.3rem' };
  const itemStyle = (selected) => ({ padding: '0.4rem 0.6rem', borderRadius: '6px', cursor: 'pointer', background: selected ? '#dbeafe' : 'white', display: 'flex', alignItems: 'center', gap: '0.5rem', fontSize: '0.9rem' });

  return (
    <div className="bg-wrapper">
      <div className="bg-content">
        <h1 className="page-title text-blue" style={{ textAlign: 'center' }}>Schedule Meetings (Principal)</h1>
        <div className="card" style={{ maxWidth: '700px', margin: '0 auto' }}>
          <form onSubmit={handleSubmit}>
            <div className="form-group">
              <label>Select Mode</label>
              <input type="text" value="Selected Staff / HODs" readOnly style={{ background: '#f9fafb' }} />
              <small style={{ color: '#6b7280' }}>For "Selected", choose names from the lists below.</small>
            </div>

            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '1rem' }}>
              <div className="form-group">
                <label>Meeting Date</label>
                <input type="date" value={form.date} onChange={e => setForm({ ...form, date: e.target.value })} required />
              </div>
              <div className="form-group">
                <label>Meeting Time</label>
                <input type="time" value={form.time} onChange={e => setForm({ ...form, time: e.target.value })} required />
              </div>
            </div>

            <div className="form-group">
              <label>Meeting Title</label>
              <input type="text" placeholder="e.g. Semester Beginning Review" value={form.title} onChange={e => setForm({ ...form, title: e.target.value })} required />
            </div>

            <div className="form-group">
              <label>Agenda / Subject</label>
              <textarea rows="3" placeholder="Enter agenda..." value={form.agenda} onChange={e => setForm({ ...form, agenda: e.target.value })} />
            </div>

            <div className="form-group">
              <label>Meeting Link (optional)</label>
              <input type="text" placeholder="https://meet.google.com/xxx" value={form.meetingLink} onChange={e => setForm({ ...form, meetingLink: e.target.value })} />
            </div>

            <div className="form-group">
              <label>Venue (optional)</label>
              <input type="text" placeholder="e.g. Conference Hall" value={form.venue} onChange={e => setForm({ ...form, venue: e.target.value })} />
            </div>

            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '1rem' }}>
              <div className="form-group">
                <label>Select Staff (optional) — {form.selectedStaff.length} selected</label>
                <div style={listStyle}>
                  {staff.length === 0 ? <p style={{ color: '#6b7280', padding: '0.5rem', fontSize: '0.85rem' }}>No staff registered yet</p> :
                    staff.map(s => (
                      <div key={s._id} style={itemStyle(form.selectedStaff.includes(s._id))} onClick={() => toggleSelect(s._id, 'selectedStaff')}>
                        <input type="checkbox" readOnly checked={form.selectedStaff.includes(s._id)} />
                        {s.name} ({s.email})
                      </div>
                    ))}
                </div>
                <small style={{ color: '#6b7280' }}>Use Ctrl (or Cmd) to select multiple.</small>
              </div>
              <div className="form-group">
                <label>Select HODs (optional) — {form.selectedHods.length} selected</label>
                <div style={listStyle}>
                  {hods.length === 0 ? <p style={{ color: '#6b7280', padding: '0.5rem', fontSize: '0.85rem' }}>No HODs approved yet</p> :
                    hods.map(h => (
                      <div key={h._id} style={itemStyle(form.selectedHods.includes(h._id))} onClick={() => toggleSelect(h._id, 'selectedHods')}>
                        <input type="checkbox" readOnly checked={form.selectedHods.includes(h._id)} />
                        {h.name} ({h.department})
                      </div>
                    ))}
                </div>
                <small style={{ color: '#6b7280' }}>You can leave either side empty.</small>
              </div>
            </div>

            {error && <div className="alert alert-error">❌ {error}</div>}

            <button type="submit" className="btn btn-primary" disabled={loading} style={{ width: '100%', padding: '0.9rem', fontSize: '1rem', marginTop: '0.5rem' }}>
              {loading ? 'Scheduling...' : 'Schedule Meetings'}
            </button>
          </form>
        </div>
      </div>
    </div>
  );
}

export default PrincipalSchedule;
